using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Interop;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoInspect {
 const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
 const string RefDir=@"\\Server\DropBox\Работа server\4. Техдепартамент\4.1. Проекты\098 Ташкент-КТ\5 ПИР\5.5_Том 4 Пост охраны\01_ELF-D1-03-ЭОМ";
 static void Walk(IAcSmSubset sub,string section,List<object> rows){var en=sub.GetSheetEnumerator();IAcSmComponent c;while((c=en.Next())!=null){if(c.GetTypeName()=="AcSmSheet"){var s=(IAcSmSheet)c;var l=s.GetLayout();rows.Add(new{Section=section,Number=s.GetNumber(),Title=s.GetTitle(),File=l.GetFileName(),Layout=l.GetName(),Id=s.GetObjectId().GetHandle()});}else if(c.GetTypeName()=="AcSmSubset")Walk((IAcSmSubset)c,section+"/"+c.GetName(),rows);}}
 static object InspectFile(string file){using(var db=new Database(false,true)){db.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,false,null);db.CloseInput(true);using(var tr=db.TransactionManager.StartTransaction()){var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var layouts=new List<object>();foreach(DBDictionaryEntry entry in ld){var l=(Layout)tr.GetObject(entry.Value,OpenMode.ForRead);var b=(BlockTableRecord)tr.GetObject(l.BlockTableRecordId,OpenMode.ForRead);var ents=new List<object>();foreach(ObjectId id in b){var e=tr.GetObject(id,OpenMode.ForRead);if(e is MText m)ents.Add(new{Type="MText",Handle=m.Handle.ToString(),Text=m.Text,Pos=new[]{m.Location.X,m.Location.Y},Height=m.TextHeight,Width=m.Width});else if(e is DBText t)ents.Add(new{Type="Text",Handle=t.Handle.ToString(),Text=t.TextString,Pos=new[]{t.Position.X,t.Position.Y},Height=t.Height});else if(e is BlockReference br){var root=(BlockTableRecord)tr.GetObject(br.IsDynamicBlock?br.DynamicBlockTableRecord:br.BlockTableRecord,OpenMode.ForRead);var attrs=br.AttributeCollection.Cast<ObjectId>().Select(x=>(AttributeReference)tr.GetObject(x,OpenMode.ForRead)).Select(a=>new{Tag=a.Tag,Text=a.TextString}).ToArray();ents.Add(new{Type="Block",Handle=br.Handle.ToString(),Name=root.Name,Attributes=attrs});}else if(e is Viewport v)ents.Add(new{Type="Viewport",Handle=v.Handle.ToString(),Number=v.Number,Width=v.Width,Height=v.Height,Center=new[]{v.CenterPoint.X,v.CenterPoint.Y},Target=new[]{v.ViewTarget.X,v.ViewTarget.Y},ViewCenter=new[]{v.ViewCenter.X,v.ViewCenter.Y},Scale=v.CustomScale});}layouts.Add(new{Name=l.LayoutName,Model=l.ModelType,Order=l.TabOrder,Entities=ents});}return new{File=file,Layouts=layouts};}}}
 [CommandMethod("CODEXUGOINSPECT",CommandFlags.Session)]public void Run(){try{var mgr=new AcSmSheetSetMgrClass();var db=mgr.OpenDatabase(Path.Combine(RefDir,"ELF-D1-03-ЭОМ.dst"),false);var rows=new List<object>();Walk((IAcSmSubset)db.GetSheetSet(),"",rows);var files=new[]{Path.Combine(RefDir,"01_Титул.DWG"),Path.Combine(RefDir,"Типовые узлы.dwg")};File.WriteAllText(Path.Combine(Folder,"reference.json"),JsonSerializer.Serialize(new{SheetSet=rows,Drawings=files.Select(InspectFile).ToArray()},new JsonSerializerOptions{WriteIndented=true}));}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"inspect_error.txt"),ex.ToString());}}
}